// FuelPage.js

import React, { useState, useEffect } from 'react';
import styled from 'styled-components';
import axios from 'axios';

const FuelPageContainer = styled.div`
  padding: 20px;
`;

const Header = styled.h2`
  font-size: 24px;
  color: #333;
`;

const InputField = styled.input`
  padding: 10px;
  margin: 10px 0;
  width: 100%;
  border: 1px solid #ddd;
  border-radius: 5px;
`;

const Button = styled.button`
  padding: 10px 20px;
  background-color: #007bff;
  color: white;
  border: none;
  border-radius: 5px;
  cursor: pointer;

  &:hover {
    background-color: #0056b3;
  }
`;

const FuelTable = styled.table`
  width: 100%;
  margin-top: 20px;
  border-collapse: collapse;
`;

const TableHeader = styled.th`
  background-color: #f2f2f2;
  padding: 12px;
  text-align: left;
`;

const TableCell = styled.td`
  padding: 12px;
  border: 1px solid #ddd;
`;

const FuelPage = () => {
  const [fuelDetails, setFuelDetails] = useState([]);
  const [lorryId, setLorryId] = useState('');
  const [fuelDate, setFuelDate] = useState('');
  const [bunkName, setBunkName] = useState('');
  const [totalAmount, setTotalAmount] = useState('');
  const [amountPaid, setAmountPaid] = useState('');

  const fetchFuelDetails = () => {
    axios
      .get(`/api/fuel/${lorryId}`)
      .then(response => {
        setFuelDetails(response.data);
      })
      .catch(error => {
        console.error('Error fetching fuel details:', error);
      });
  };

  const handleAddFuelDetails = () => {
    const data = {
      lorry_id: lorryId,
      fuel_date: fuelDate,
      bunk_name: bunkName,
      total_amount: totalAmount,
      amount_paid: amountPaid
    };

    axios
      .post('/api/fuel/add', data)
      .then(response => {
        alert(response.data.message);
        fetchFuelDetails(); // Fetch updated details
      })
      .catch(error => {
        console.error('Error adding fuel details:', error);
      });
  };

  return (
    <FuelPageContainer>
      <Header>Fuel Details</Header>
      <div>
        <InputField
          type="number"
          placeholder="Lorry ID"
          value={lorryId}
          onChange={e => setLorryId(e.target.value)}
        />
        <InputField
          type="date"
          value={fuelDate}
          onChange={e => setFuelDate(e.target.value)}
        />
        <InputField
          type="text"
          placeholder="Bunk Name"
          value={bunkName}
          onChange={e => setBunkName(e.target.value)}
        />
        <InputField
          type="number"
          placeholder="Total Amount"
          value={totalAmount}
          onChange={e => setTotalAmount(e.target.value)}
        />
        <InputField
          type="number"
          placeholder="Amount Paid"
          value={amountPaid}
          onChange={e => setAmountPaid(e.target.value)}
        />
        <Button onClick={handleAddFuelDetails}>Add Fuel Details</Button>
      </div>

      <Button onClick={fetchFuelDetails}>Details</Button>

      {fuelDetails.length > 0 && (
        <FuelTable>
          <thead>
            <tr>
              <TableHeader>Date</TableHeader>
              <TableHeader>Bunk Name</TableHeader>
              <TableHeader>Total Amount</TableHeader>
              <TableHeader>Amount Paid</TableHeader>
              <TableHeader>Remaining Amount</TableHeader>
            </tr>
          </thead>
          <tbody>
            {fuelDetails.map((fuel, index) => (
              <tr key={index}>
                <TableCell>{fuel.fuel_date}</TableCell>
                <TableCell>{fuel.bunk_name}</TableCell>
                <TableCell>{fuel.total_amount}</TableCell>
                <TableCell>{fuel.amount_paid}</TableCell>
                <TableCell>{fuel.remaining_amount}</TableCell>
              </tr>
            ))}
          </tbody>
        </FuelTable>
      )}
    </FuelPageContainer>
  );
};

export default FuelPage;
